import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        long mod = sc.nextLong();

        long[][] C = new long[n + 1][n + 1];
        long[] w = new long[n + 1];
        long[] dp = new long[n + 1];
        long[][] dp2 = new long[n + 2][m + 1];
        long[][] w2 = new long[n + 2][m + 1];

        // Compute binomial coefficients
        C[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
            }
        }

        // Initialize w array
        w[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                long current = C[i - 1][j - 1] * w[j - 1] % mod * w[i - j] % mod;
                w[i] = (w[i] + current * (i + 1)) % mod;

                long part1 = (dp[j - 1] * w[i - j] + w[j - 1] * dp[i - j]) % mod;
                long part2 = (long)( (i - j) * (i - j + 1) / 2 + j * (j - 1) / 2 );

                long contribution = (C[i - 1][j - 1] * part1) % mod * (i + 1) % mod;
                contribution = (contribution + current * part2) % mod;
                dp[i] = (dp[i] + contribution) % mod;
            }
        }

        // Initialize w2 and dp2
        w2[0][0] = 1;
        for (int i = 1; i <= n + 1; i++) {
            for (int k = 0; k <= m; k++) {
                for (int j = 1; j <= Math.min(i - 1, k); j++) {
                    int pi = i - j - 1;
                    int pk = k - j;
                    long cw = C[k][j];

                    w2[i][k] = (w2[i][k] + cw * w2[pi][pk] % mod * w[j]) % mod;

                    long temp1 = cw * w2[pi][pk] % mod * dp[j] % mod;
                    long temp2 = cw * dp2[pi][pk] % mod * w[j] % mod;

                    dp2[i][k] = (dp2[i][k] + temp1 + temp2) % mod;
                }
            }
            for (int j = 0; j <= m; j++) {
                if (i - 1 >= 0) {
                    dp2[i][j] = (dp2[i][j] + dp2[i - 1][j]) % mod;
                    w2[i][j] = (w2[i][j] + w2[i - 1][j]) % mod;
                }
            }
        }

        System.out.println(dp2[n + 1][m]);
        sc.close();
    }
}

